// What a package that publishes to npm must and must not carry, checked on the list of files npm
// would pack (`npm pack --dry-run --json`) or on an unpacked tarball, with the files' contents read
// from the folder. One definition for the pack tests of the three packages and for the release
// workflow, so what a test accepts is what the release publishes.
//
// A tarball must carry: package.json, LICENSE, NOTICE (generated by scripts/npm/prepack.mjs) and
// README.md, and every file the manifest's `main`, `types`, `bin` and `exports` point at. It must
// not carry: TypeScript source (declarations are fine), tests, source maps (a release asset
// carries them), `node_modules`, or a text that names the machine it was built on. Its manifest must
// be publishable: not private, no `file:`, `link:` or `workspace:` specifier among the
// dependencies a consumer installs, none of the repository's private packages among them, and
// `publishConfig` with public access and provenance.
//
//   node scripts/npm/pack-check.mjs <package folder>...       the files npm would pack, after prepack
//   node scripts/npm/pack-check.mjs --tarball <file.tgz>...   the files of a tarball npm packed
//
// Prints a size report for each package and exits 1 on any problem.
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, readdirSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

import { entryTargets } from "./prepack.mjs";

const repo = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");

/** The repository's packages that do not publish: a published file must not import them. */
export const PRIVATE_PACKAGES = ["@argusvane/datum-engine", "@argusvane/datum-pdf-kernel", "@argusvane/datum-quickjs-wasm-host", "@argusvane/datum-submissions"];

export const REQUIRED_FILES = ["package.json", "LICENSE", "NOTICE", "README.md"];

/** Files read as text for the absolute-path and private-import scans. */
const TEXT = /\.(?:m?js|cjs|json|md|txt|html|css|svg|d\.ts|d\.mts|d\.cts)$/;
const TS_SOURCE = /\.(?:ts|tsx|mts|cts)$/;
const DECLARATION = /\.d\.(?:ts|mts|cts)$/;
/** A reference to the machine a build ran on: a home folder, a runner's workspace, a scratch folder. */
const MACHINE_PATH = [/\/Users\/[A-Za-z0-9._-]+\//, /\/home\/(?:runner|[a-z][a-z0-9_-]*)\/(?:work|\.|Documents|projects|src)/, /\/private\/(?:tmp|var)\//, /[A-Za-z]:\\Users\\[A-Za-z0-9._-]+\\/, /\/__w\/[^/\s]+\/[^/\s]+\//];
/** A specifier of a private package in an import or an export-from, in source or minified. */
const PRIVATE_IMPORT = new RegExp(`(?:\\bfrom\\s*|\\bimport\\s*\\(\\s*|\\brequire\\s*\\(\\s*)["']((?:${PRIVATE_PACKAGES.map((name) => name.replace(/[/@]/g, "\\$&")).join("|")})(?:/[^"']*)?)["']`, "g");
/**
 * The one import of a private package a published file keeps: the conformance suite reaches the Node worker host
 * through a dynamic import it guards (the thread body is a file beside that package, which a single-file
 * bundle cannot carry), and reports the worker rows as skipped where the import fails.
 */
export const ALLOWED_PRIVATE_IMPORTS = ["@argusvane/datum-quickjs-wasm-host/worker"];

/** Every file under `folder` as `{ path (posix, relative), size }`. */
export function filesOf(folder) {
  const files = [];
  const walk = (dir) => {
    for (const name of readdirSync(dir)) {
      const path = join(dir, name);
      if (statSync(path).isDirectory()) {
        walk(path);
      } else {
        files.push({ path: path.slice(folder.length + 1).split(sep).join("/"), size: statSync(path).size });
      }
    }
  };
  walk(folder);
  return files.sort((a, b) => a.path.localeCompare(b.path));
}

/**
 * The problems of one package: `folder` holds its files (the package folder, or an unpacked tarball's
 * `package/`), `files` is the list that would ship, `{ path, size }` each.
 */
export function packProblems(folder, files) {
  const problems = [];
  const paths = new Set(files.map((file) => file.path));
  const manifest = JSON.parse(readFileSync(join(folder, "package.json"), "utf8"));
  const label = manifest.name ?? folder;
  const fail = (text) => problems.push(`${label}: ${text}`);

  for (const required of REQUIRED_FILES) {
    if (!paths.has(required)) {
      fail(`${required} is not in the package`);
    }
  }
  for (const target of entryTargets(manifest)) {
    if (!paths.has(target)) {
      fail(`package.json points at ${target}, which is not in the package`);
    }
  }

  if (manifest.private === true) fail("package.json is private");
  if (manifest.license !== "MIT") fail(`license is ${JSON.stringify(manifest.license)}, not "MIT"`);
  if (!manifest.repository?.url) fail("package.json has no repository.url (provenance needs it)");
  if (manifest.publishConfig?.access !== "public") fail('publishConfig.access is not "public"');
  if (manifest.publishConfig?.provenance !== true) fail("publishConfig.provenance is not true");
  if (!Array.isArray(manifest.files) || manifest.files.length === 0) fail("package.json has no files allowlist");
  for (const key of ["dependencies", "optionalDependencies", "peerDependencies"]) {
    for (const [name, range] of Object.entries(manifest[key] ?? {})) {
      if (/^(?:file|link|workspace|git\+|github:|https?:)/.test(range)) fail(`${key} "${name}" is "${range}", which a consumer cannot install`);
      if (PRIVATE_PACKAGES.includes(name)) fail(`${key} names ${name}, which is not published`);
    }
  }

  for (const { path } of files) {
    if (TS_SOURCE.test(path) && !DECLARATION.test(path)) fail(`${path} is TypeScript source`);
    if (path.endsWith(".map")) fail(`${path} is a source map (maps are a release asset)`);
    if (/(^|\/)(?:tests?|__tests__|node_modules)\//.test(path) || /\.(?:test|spec)\.[cm]?[jt]sx?$/.test(path)) fail(`${path} is a test or a dependency folder`);
    if (/^(?:src|scripts|tests)\//.test(path)) fail(`${path} is a source folder`);
  }

  const here = repo.length > 8 ? repo : "\0";
  for (const { path, size } of files) {
    if (!TEXT.test(path) || size > 64 * 1024 * 1024) {
      continue;
    }
    const text = readFileSync(join(folder, path), "utf8");
    if (text.includes(here)) fail(`${path} names the checkout's path`);
    const machine = MACHINE_PATH.find((pattern) => pattern.test(text));
    if (machine) fail(`${path} names a build machine's path (${machine.exec(text)?.[0]})`);
    if (/\.(?:m?js|cjs|d\.ts|d\.mts)$/.test(path)) {
      const named = [...text.matchAll(PRIVATE_IMPORT)].find((match) => !ALLOWED_PRIVATE_IMPORTS.includes(match[1]));
      if (named) fail(`${path} imports a package that is not published (${named[0]})`);
    }
  }
  return problems;
}

/** A size report: the totals and the largest top-level entries (a folder counts as one). */
export function sizeReport(name, files, packedBytes) {
  const unpacked = files.reduce((sum, file) => sum + file.size, 0);
  const top = new Map();
  for (const { path, size } of files) {
    const key = path.includes("/") ? `${path.split("/")[0]}/` : path;
    top.set(key, (top.get(key) ?? 0) + size);
  }
  const lines = [`${name}: ${files.length} files, ${packedBytes === undefined ? "" : `${(packedBytes / 1024 / 1024).toFixed(2)} MB packed, `}${(unpacked / 1024 / 1024).toFixed(2)} MB unpacked`];
  for (const [key, size] of [...top].sort((a, b) => b[1] - a[1]).slice(0, 6)) {
    lines.push(`    ${key.padEnd(28)} ${(size / 1024).toFixed(0).padStart(8)} KB`);
  }
  return lines.join("\n");
}

/** `npm pack --dry-run --json` in `folder`: `{ name, files: [{ path, size }], size, unpackedSize }`. Scripts are not run (the build and prepack ran already). */
export function dryRunPack(folder) {
  const out = execFileSync(process.platform === "win32" ? "npm.cmd" : "npm", ["pack", "--dry-run", "--json", "--ignore-scripts"], { cwd: folder, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  return JSON.parse(out)[0];
}

/** Unpacks a tarball into a new scratch folder: returns the `package/` folder and a cleanup function. */
export function unpackTarball(tarball) {
  const scratch = mkdtempSync(join(tmpdir(), "datum-tarball-"));
  execFileSync("tar", ["-xzf", resolve(tarball), "-C", scratch]);
  return { folder: join(scratch, "package"), cleanup: () => rmSync(scratch, { recursive: true, force: true }) };
}

function main() {
  const args = process.argv.slice(2);
  const tarballs = args[0] === "--tarball";
  const targets = tarballs ? args.slice(1) : args;
  if (targets.length === 0) {
    console.error("usage: node scripts/npm/pack-check.mjs <package folder>... | --tarball <file.tgz>...");
    process.exit(2);
  }
  const problems = [];
  for (const target of targets) {
    if (tarballs) {
      const { folder, cleanup } = unpackTarball(target);
      try {
        const files = filesOf(folder);
        problems.push(...packProblems(folder, files));
        console.log(sizeReport(JSON.parse(readFileSync(join(folder, "package.json"), "utf8")).name, files, statSync(target).size));
      } finally {
        cleanup();
      }
    } else {
      const folder = resolve(target);
      execFileSync(process.execPath, [join(repo, "scripts", "npm", "prepack.mjs")], { cwd: folder, stdio: "inherit" });
      const info = dryRunPack(folder);
      problems.push(...packProblems(folder, info.files));
      console.log(sizeReport(info.name, info.files, info.size));
    }
  }
  if (problems.length > 0) {
    console.error(`pack-check: ${problems.length} problem${problems.length === 1 ? "" : "s"}:\n  ${problems.join("\n  ")}`);
    process.exit(1);
  }
  console.log("pack-check: ok");
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
